insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"97e75efb-7b3a-4a9e-8114-4a04fa1bb201","control_id":"A-GEN-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify timely filing of GSTR-1, GSTR-3B, GSTR-9/9C and other applicable returns and quantify late fee and interest leakages.","law_refs":["CGST-ACT-S37","CGST-ACT-S39","CGST-ACT-S44","CGST-ACT-S47","CGST-RULE-59"],"required_data":["gstr1","gstr3b","gstr9","electronic_cash_ledger"],"procedure":"1. Download the return filing status for all GSTINs for the audit period.\\n2. Compare filing dates with statutory due dates (including notified extensions) for each return.\\n3. Recompute late fee for each delayed return and compare with the amount paid through the cash ledger.\\n4. Check whether GSTR-1 filing was blocked under Rule 59(6) and whether that delayed customer ITC.\\n5. Record any return not yet filed and the three-year bar on furnishing returns after due date.","automation":null,"expected_result":"All returns filed on or before due dates; late fees, if any, correctly paid.","exception_conditions":"Returns delayed or unfiled; late fee short-paid; return approaching the three-year filing bar.","risk_level":"medium","exposure_basis":"Late fee u/s 47 at notified rates and caps; interest u/s 50(1) on tax paid late; customer disputes from delayed GSTR-1.","evidence_required":["Return filing status screenshots/export","Cash ledger extract for late fee debit","Due-date calendar with extension notifications"],"corrective_action":"File pending returns immediately, pay late fee and interest, and implement a compliance calendar with maker-checker sign-off.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.247558+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"05bdd78b-842b-497b-9208-ab871e162b0a","control_id":"A-REG-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure every location from which goods are supplied, stored or services rendered is declared as principal or additional place of business, so that ITC, e-way bills and books of account are compliant.","law_refs":["CGST-ACT-S22","CGST-ACT-S25","CGST-ACT-S28","CGST-RULE-19","CGST-ACT-S35","CGST-ACT-S125"],"required_data":["general_ledger","eway_bill_register","stock_register","trial_balance"],"procedure":"1. Download the current registration certificate (REG-06) and amendment history for each GSTIN.\\n2. Compile a list of physical locations from the fixed asset register, rent agreements, electricity/rent ledgers, insurance policies and stock locations in the ERP.\\n3. Extract dispatch-from and ship-to addresses from the e-way bill register (outward and inward) and compare with registered addresses.\\n4. Identify unregistered locations, including third-party warehouses, consignment stockists, C&F agents and project sites.\\n5. For each gap, determine the date the place of business commenced and whether REG-14 was filed within 15 days.","automation":null,"expected_result":"Every operating location is reflected in the registration certificate of the correct State GSTIN before commencement of operations.","exception_conditions":"Godown or warehouse appearing in e-way bills or stock records but not on REG-06; location in a State without any registration; amendment filed more than 15 days after commencement.","risk_level":"high","exposure_basis":"Penalty u/s 125 (up to Rs 25,000 per contravention) / u/s 122; risk of detention u/s 129 for goods moving from undeclared premises; potential denial of ITC for goods received at unregistered premises; where a new State is involved, tax and interest on supplies made without registration.","evidence_required":["REG-06 and amendment orders","Rent/lease agreements and utility bills for each premises","E-way bill address extract","Location master from ERP"],"corrective_action":"File REG-14 for non-core amendment to add the place of business with supporting documents; obtain new registration where location is in a new State; update ERP location master and e-way bill dispatch addresses.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.253502+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"479f328c-01a6-43e6-b2d9-1273a50344fd","control_id":"A-REG-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["multi_gstin"],"objective":"Verify that each State registration operates as a distinct person, with inter-unit supplies of goods and services invoiced and taxed under Schedule I.","law_refs":["CGST-ACT-S25-4","CGST-ACT-SCH1-2","CGST-RULE-28","CIRC-199-11-2023"],"required_data":["sales_register","general_ledger","eway_bill_register","journal_vouchers"],"procedure":"1. List all GSTINs under the PAN and map them to legal entity ledgers and cost centres.\\n2. Extract inter-branch/stock-transfer ledgers and journal vouchers posting inter-unit charges.\\n3. Verify that each inter-State stock transfer is supported by a tax invoice (not a delivery challan) with IGST charged and e-way bill generated.\\n4. Verify that services rendered by HO or one unit to another (management, IT, shared services) are either cross-charged with tax or routed through ISD as applicable.\\n5. Check valuation of stock transfers against Rule 28 (open market value / 90% of price to unrelated customers at option / invoice value where recipient eligible for full credit).","automation":null,"expected_result":"All inter-GSTIN movements and services are invoiced and reported in GSTR-1 of the supplying unit, with matching ITC in the receiving unit.","exception_conditions":"Stock transfers on delivery challan; inter-unit services recovered through journal entries without invoice; receiving unit has exempt or non-business supplies but value adopted is nil/arbitrary.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Where recipient is fully eligible to ITC, exposure is generally revenue-neutral but interest and penalty remain.","evidence_required":["Inter-branch ledger extracts","Stock transfer invoices and e-way bills","Cross-charge policy and computation","GSTR-1 of supplying units"],"corrective_action":"Raise tax invoices for untaxed inter-unit supplies, pay tax with interest through GSTR-3B/DRC-03, document cross-charge valuation methodology, and configure ERP to block stock transfers without invoice.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.257665+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"50c4bc4e-16a9-4504-8b62-268874bba0d2","control_id":"A-REG-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure GSTINs used in invoices and ITC claims are structurally valid, active, and belong to the correct legal name and State.","law_refs":["CGST-ACT-S16-2","CGST-ACT-S29","CGST-RULE-46","CGST-ACT-S31"],"required_data":["vendor_master","customer_master","purchase_register","sales_register"],"procedure":"1. Run checksum and format validation (15 characters, State code, PAN, entity code, check digit) on all GSTINs in vendor and customer masters and transaction registers.\\n2. Validate State code of GSTIN against the billing address State in the master.\\n3. Bulk-verify status (active / suspended / cancelled, with effective dates) and legal name through the GST portal search or GSP API.\\n4. Flag transactions dated after the cancellation effective date of the counterparty.\\n5. Check that B2B invoices carry the customer''s GSTIN and are not reported as B2C.","automation":{"key": "INVALID_GSTIN", "engine": "check"},"expected_result":"All GSTINs pass checksum, match PAN and State, and are active on transaction dates.","exception_conditions":"Invalid checksum; GSTIN State code differs from address; cancelled/suspended GSTIN on transaction date; legal name mismatch; B2B customer reported without GSTIN.","risk_level":"medium","exposure_basis":"ITC on invoices from cancelled/invalid GSTINs reversed with interest u/s 50(3) where utilised; outward supplies reported against wrong GSTIN lead to customer ITC denial and commercial claims.","evidence_required":["GSTIN validation report with portal status","Vendor/customer master extract","Exception list with transaction references"],"corrective_action":"Correct masters, amend GSTR-1 records (B2B/B2C reclassification) within the Section 37 time window, stop further payments and ITC on cancelled-vendor invoices, and institute periodic automated GSTIN validation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.260794+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fc4a3b45-e6d8-46fc-95b0-a7a92668ddcd","control_id":"A-REG-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Confirm that changes to core and non-core particulars (name, constitution, address, authorised signatories, business activities, bank accounts) are updated within 15 days.","law_refs":["CGST-ACT-S28","CGST-RULE-19","CGST-ACT-S125"],"required_data":["general_ledger","bank_payments"],"procedure":"1. Obtain board resolutions, ROC filings and HR records for changes in directors, authorised signatories, name or address during the period.\\n2. Compare current bank accounts used for GST refunds and payments with bank accounts on the registration.\\n3. Compare principal business activities and HSN/SAC on registration with actual top revenue lines.\\n4. Check REG-14 filing dates against the change dates.","automation":null,"expected_result":"Registration reflects current particulars, with amendments filed within 15 days of each change.","exception_conditions":"Former director still listed as authorised signatory; refund bank account not on registration; new business line (e.g., services) not reflected.","risk_level":"low","exposure_basis":"General penalty u/s 125 (up to Rs 25,000); refund processing delays where bank account not validated.","evidence_required":["REG-06 and amendment history","Board resolutions / ROC forms","Bank account confirmations"],"corrective_action":"File REG-14 for pending changes; implement a registration change checklist owned by company secretarial and tax teams.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.264592+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"5e55acca-159c-4180-9974-0bfd3cccbd53","control_id":"A-REG-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect vendors whose registration was suspended or cancelled (including retrospective cancellation) so that ITC exposure is identified early.","law_refs":["CGST-ACT-S29","CGST-RULE-21A","CGST-ACT-S16-2","CGST-RULE-86A"],"required_data":["vendor_master","gstr2b","purchase_register","bank_payments"],"procedure":"1. Pull registration status for all vendors with purchases above a materiality threshold during the audit period.\\n2. Identify vendors with cancellation effective dates that precede invoice dates (retrospective cancellation).\\n3. Check whether ITC from such vendors has been claimed and whether those invoices appear in GSTR-2B.\\n4. Review vendor payment status and whether the vendor filed GSTR-3B for the relevant periods (GSTR-2A/2B filing status).\\n5. Evaluate commercial recovery from the vendor (indemnity clauses, retention, withheld payments).","automation":null,"expected_result":"No ITC claimed on invoices issued by vendors after their cancellation effective date; risk list maintained for suspended vendors.","exception_conditions":"ITC on invoices from retrospectively cancelled vendors; payment released despite vendor non-filing; vendor flagged as non-existent.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Recoverable from vendor where contract permits.","evidence_required":["Vendor status report with dates","Purchase register extract for affected vendors","Vendor correspondence and contract clauses"],"corrective_action":"Reverse ITC in GSTR-3B Table 4(B)(2) (or 4(B)(1) if permanent), withhold payments, invoke indemnity, and add vendor compliance rating to procurement approval workflow.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.267896+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"1e981d54-99c7-47ee-9695-64dbef4ba8d1","control_id":"B-OUT-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Confirm that every outward supply, credit note and debit note recorded in books is reported in GSTR-1/1A in the correct period, table, GSTIN and tax head.","law_refs":["CGST-ACT-S37","CGST-ACT-S35","CGST-RULE-59","CGST-RULE-46"],"required_data":["sales_register","gstr1","gstr1a","trial_balance"],"procedure":"1. Reconcile total sales/revenue in the trial balance to the sales register (including other income and FA sales) by GSTIN.\\n2. Match sales register to GSTR-1/1A at document level using GSTIN + document number + date + taxable value + tax.\\n3. Classify unmatched items: in books not in GSTR-1, in GSTR-1 not in books, value/tax mismatch, period mismatch, wrong table (B2B vs B2C, export vs domestic).\\n4. For period mismatches, check whether the later reporting was accompanied by tax payment with interest.\\n5. Summarise net differences by month and tax head and agree with GSTR-1 vs GSTR-3B variance.","automation":{"type": "BOOKS_GSTR1", "engine": "recon"},"expected_result":"Document-level match with no unexplained differences; timing items cleared in subsequent periods with interest.","exception_conditions":"Invoices missing from GSTR-1; duplicates in GSTR-1; customer GSTIN errors; credit notes reported without corresponding books entry.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Reconciliation workpaper by GSTIN and month","GSTR-1 JSON/Excel downloads","Sales register extract","Trial balance revenue mapping"],"corrective_action":"Report missing documents in the next GSTR-1 or amend through Table 9A/GSTR-1A within the time limit; pay differential tax with interest through GSTR-3B or DRC-03.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.271994+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"b46759e3-a32e-4823-90cd-249479328f1d","control_id":"B-OUT-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure tax declared in GSTR-1 has been paid through GSTR-3B for each period and head, and anticipate DRC-01B intimations.","law_refs":["CGST-ACT-S39","CGST-ACT-S37","CGST-RULE-88C","CGST-ACT-S50-1"],"required_data":["gstr1","gstr3b","electronic_liability_register"],"procedure":"1. Extract tax liability by head (IGST, CGST, SGST, cess) from GSTR-1 (net of amendments and credit notes) and GSTR-3B Table 3.1 for each month.\\n2. Compute month-wise and cumulative differences for the financial year.\\n3. For liability shortfalls in GSTR-3B, identify document-level causes using B-OUT-001 results.\\n4. Check whether shortfalls were subsequently paid in later GSTR-3B or DRC-03 and whether interest was paid.\\n5. Check the portal for any DRC-01B intimation and the reply filed (Part B).","automation":{"type": "GSTR1_GSTR3B", "engine": "recon"},"expected_result":"Cumulative GSTR-3B liability equals or exceeds GSTR-1 liability for each head, with timing differences paid with interest.","exception_conditions":"GSTR-1 liability exceeds GSTR-3B without later payment; interest not paid on delayed liability; DRC-01B unanswered.","risk_level":"critical","exposure_basis":"Shortfall in tax + interest u/s 50(1) @ 18% from original due date; summary recovery risk u/s 75(12) for self-assessed tax declared in GSTR-1 but not paid.","evidence_required":["Month-wise liability comparison","DRC-01B and reply (if any)","DRC-03 / subsequent GSTR-3B showing payment"],"corrective_action":"Pay shortfall with interest via DRC-03 or next GSTR-3B; respond to DRC-01B with reconciliation; correct GSTR-1 where over-reported.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.274691+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"376acb5a-03ab-4f37-83f4-e5b13bca2f77","control_id":"B-OUT-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect duplicate invoice numbers, re-used series and gaps that may indicate double reporting, suppression or non-compliance with Rule 46.","law_refs":["CGST-ACT-S31","CGST-RULE-46"],"required_data":["sales_register","gstr1"],"procedure":"1. Sort sales register by GSTIN, document series and number for each financial year.\\n2. Identify identical document numbers within the same GSTIN and financial year (case-insensitive, stripping prefixes and spaces).\\n3. Identify identical customer + date + value combinations under different numbers (potential double booking).\\n4. Identify gaps in numbering and obtain explanations (cancelled invoices, voided documents) and reconcile with GSTR-1 Table 13.\\n5. Confirm document numbers do not exceed 16 characters and each series is unique per financial year.","automation":{"key": "DUP_SALES", "engine": "check"},"expected_result":"Unique consecutive numbering per GSTIN per year; gaps explained by documented cancellations reported in Table 13.","exception_conditions":"Duplicate numbers; unexplained gaps; same supply recorded twice; series reset within the year.","risk_level":"medium","exposure_basis":"Duplicates may overstate liability (refund/adjustment opportunity) or reflect suppressed supplies (tax + interest + penalty u/s 122). Penalty for incorrect invoices u/s 122.","evidence_required":["Duplicate/gap exception report","Cancelled invoice log","GSTR-1 Table 13 document summary"],"corrective_action":"Cancel or credit-note genuine duplicates, investigate gaps, and enforce system-generated non-editable numbering by GSTIN and year.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.277762+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"568490d6-db81-48ae-82f8-f3e32ca1be67","control_id":"F-EINV-004","version":1,"effective_from":"2023-11-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure IRN generation within 30 days of document date for notified AATO classes.","law_refs":["ADV-EINV-30DAY","CGST-RULE-48-4"],"required_data":["einvoice_register","sales_register"],"procedure":"1. Compute lag between document date and IRN acknowledgement date for each document.\\n2. Flag documents with lag beyond 30 days and those rejected by IRP for this reason.\\n3. Determine how rejected documents were handled (re-dated, issued without IRN).","automation":null,"expected_result":"IRNs generated promptly, well within 30 days.","exception_conditions":"Backdated invoices; credit notes not e-invoiced due to lapse; re-dating to circumvent restriction.","risk_level":"medium","exposure_basis":"Invalid documents leading to customer ITC denial; liability timing errors + interest.","evidence_required":["IRN lag analysis"],"corrective_action":"Enforce real-time IRN generation and monitor lag weekly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.468341+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"7692fe3e-f68b-427a-abb8-993b2f0e94a6","control_id":"B-OUT-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify that the rate charged on each outward supply is consistent with the HSN/SAC and the applicable rate notification at the time of supply.","law_refs":["CGST-ACT-S9-1","NOTIF-1-2017-CTR","NOTIF-11-2017-CTR","CGST-RULE-46"],"required_data":["sales_register","gstr1","customer_master"],"procedure":"1. Build an item/HSN-to-rate matrix effective date-wise, including rate changes during the period.\\n2. Compute effective rate per line (tax / taxable value) and compare with the expected rate for the HSN.\\n3. Flag lines with rate deviations, zero tax on taxable HSN, or multiple rates for the same item in the same period.\\n4. Review classification of top revenue items with technical literature, product catalogues and any advance ruling.\\n5. Verify HSN digits reported in GSTR-1 Table 12 meet the minimum digit requirement for the turnover band.","automation":{"key": "WRONG_RATE", "engine": "check"},"expected_result":"Rate per line equals notified rate for the HSN effective on the time of supply; HSN summary consistent with invoices.","exception_conditions":"Lower rate charged; inconsistent rates for the same item; rate change not applied from the effective date; HSN digits short.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Excess tax charged is generally not refundable where incidence passed on (unjust enrichment).","evidence_required":["Rate deviation exception report","Classification note per major product","Rate notifications applied"],"corrective_action":"Pay differential tax with interest, issue supplementary invoices/debit notes where recoverable, correct item master, and obtain classification opinion or advance ruling for disputed items.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.282462+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"6e875b2f-48db-4854-bed6-41ff51647a57","control_id":"B-OUT-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure inter-State and intra-State classification follows the place of supply rules, particularly for bill-to-ship-to, services and SEZ supplies.","law_refs":["IGST-ACT-S10","IGST-ACT-S12","IGST-ACT-S7-5","CGST-ACT-S77","IGST-ACT-S19"],"required_data":["sales_register","gstr1","customer_master","eway_bill_register"],"procedure":"1. Derive expected place of supply for each invoice from ship-to/bill-to State (goods) or recipient location and service type (services).\\n2. Compare supplier State with place of supply to determine expected head; compare with head actually charged.\\n3. Specifically test supplies to SEZ (must be IGST/zero-rated), bill-to-ship-to across States, and event/immovable property services.\\n4. For errors, determine whether the customer has taken ITC under the wrong head and the remediation path under Sections 77/19.\\n5. Check that refunds of wrong-head tax are claimed within the two-year period from date of payment under the correct head.","automation":{"key": "WRONG_TAX_HEAD", "engine": "check"},"expected_result":"Tax head on every invoice matches the place of supply determination.","exception_conditions":"CGST+SGST charged on supply to SEZ or out-of-State ship-to; IGST charged on intra-State supply; POS State in GSTR-1 differs from customer State without justification.","risk_level":"high","exposure_basis":"Tax under the correct head payable in full (no set-off of wrong-head tax); refund of wrong head available u/s 77/IGST s.19 within limitation; no interest on correct-head payment where s.77 applies.","evidence_required":["POS exception report","Contracts / delivery documents establishing POS","Customer confirmations on ITC taken"],"corrective_action":"Issue credit note and fresh invoice under the correct head (where customer cooperation available), pay correct tax, file refund of wrong-head tax, and fix POS logic in ERP tax engine.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.285708+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"6cb81398-20d3-45e5-ae95-d9bb606a8782","control_id":"B-OUT-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify credit notes declared after 30 November following the end of the financial year of the original supply (or the annual return date, if earlier) for which output tax has been reduced.","law_refs":["CGST-ACT-S34","CGST-ACT-S15-3"],"required_data":["sales_register","gstr1","gstr9"],"procedure":"1. Extract all credit notes with reference to the original invoice number and date.\\n2. Determine the financial year of the original supply and the cut-off (30 November following that year, or date of filing GSTR-9 if earlier).\\n3. Compare credit note GSTR-1 reporting date with the cut-off.\\n4. For late credit notes, check whether tax was reduced in GSTR-1/GSTR-3B or issued as financial credit notes without GST.\\n5. Confirm the ERP blocks GST credit notes beyond the cut-off.","automation":{"key": "CN_TIME_LIMIT_34_2", "engine": "check"},"expected_result":"No reduction of output tax for credit notes beyond the Section 34(2) cut-off; such credit notes issued as commercial/financial credit notes without GST.","exception_conditions":"Tax reduced through late credit notes; credit notes without original invoice reference; GSTR-9 filed early, shortening the window.","risk_level":"high","exposure_basis":"Output tax reduced through time-barred credit notes + interest u/s 50(1).","evidence_required":["Credit note register with original invoice references","GSTR-1 filing dates","GSTR-9 filing date"],"corrective_action":"Reverse the tax reduction by paying tax with interest; convert late credit notes to financial credit notes; configure ERP validation on credit note date vs original invoice FY.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.291069+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"815d1d3c-9143-451a-b558-af7a8630f139","control_id":"B-OUT-007","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect credit notes whose date precedes the referenced invoice, or that lack a valid reference, indicating data errors or tax reduction without a valid Section 34 basis.","law_refs":["CGST-ACT-S34","CGST-RULE-53"],"required_data":["sales_register","gstr1"],"procedure":"1. Join credit notes to the original invoices on reference number.\\n2. Flag credit notes where the credit note date is earlier than the original invoice date, or the referenced invoice does not exist in the sales register.\\n3. Flag credit notes where cumulative credit exceeds original invoice value or tax.\\n4. Verify the customer GSTIN on the credit note matches the original invoice.\\n5. Obtain explanation and supporting documentation for each exception.","automation":{"key": "CN_BEFORE_INVOICE", "engine": "check"},"expected_result":"Every credit note references a valid, earlier-dated invoice for the same customer with cumulative credit not exceeding the original.","exception_conditions":"Credit note precedes invoice; missing reference; credit exceeds original; GSTIN mismatch.","risk_level":"medium","exposure_basis":"Output tax reduced without valid linkage + interest u/s 50(1).","evidence_required":["Credit note to invoice mapping report","Customer correspondence / return documents"],"corrective_action":"Correct references through GSTR-1 amendment, reverse ineligible reductions with interest, and enforce mandatory invoice linkage in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.2957+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"93157ce0-04b3-4397-9539-267c30542552","control_id":"F-EINV-005","version":1,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify the entity''s e-invoice applicability considering AATO across all GSTINs under the PAN for each FY since 2017-18, and any exempt class status.","law_refs":["NOTIF-EINV-THRESHOLD","CGST-RULE-48-4"],"required_data":["gstr9","gstr3b","trial_balance"],"procedure":"1. Compute AATO for each FY from 2017-18 using PAN-level turnover.\\n2. Compare with thresholds and their effective dates.\\n3. Check claimed exemption status (SEZ unit, bank, insurer, GTA, passenger transport, multiplex).","automation":null,"expected_result":"Applicability correctly determined and implemented from the right date.","exception_conditions":"E-invoicing not started on crossing threshold; SEZ developer wrongly assuming exemption.","risk_level":"medium","exposure_basis":"All B2B invoices since applicability date invalid → customer ITC risk and penalties.","evidence_required":["AATO computation","Exemption analysis"],"corrective_action":"Commence e-invoicing immediately and assess remediation for past invoices.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.475256+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0d923cf3-93b4-4631-89d0-2ee5fb2032cb","control_id":"B-OUT-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure GST is reduced only on credit notes that arise from a Section 34 event (excess value, return, deficiency) and, for discounts, satisfy Section 15(3)(b) including pre-agreement and recipient reversal.","law_refs":["CGST-ACT-S34","CGST-ACT-S15-3","CIRC-212-06-2024","CIRC-92-11-2019"],"required_data":["sales_register","gstr1","journal_vouchers","customer_master","ims_data"],"procedure":"1. Classify credit notes by reason code: rate difference, quantity return, quality claim, volume/turnover discount, schemes, price protection, settlement.\\n2. For discounts, obtain the agreement/scheme circular and verify it existed before or at the time of supply and is linked to specific invoices.\\n3. Verify that the recipient has reversed ITC: check acceptance on IMS / credit note visibility, or obtain the recipient''s certificate (CA/CMA certificate above threshold) as per Circular 212/6/2024-GST.\\n4. Identify credit notes issued for ad hoc settlements, market support, or claims not pre-agreed and confirm they are issued without GST (financial credit notes).\\n5. Recompute output tax impact of non-qualifying GST credit notes.","automation":null,"expected_result":"GST credit notes only where Section 34/15(3) conditions met with documented pre-agreement and recipient reversal evidence.","exception_conditions":"Discount schemes announced after supply; no invoice linkage; recipient ITC reversal not evidenced; recipient rejected credit note on IMS.","risk_level":"high","exposure_basis":"Output tax reduced on non-qualifying credit notes + interest u/s 50(1) @ 18%.","evidence_required":["Credit note reason analysis","Scheme/agreement copies with dates","Recipient ITC reversal certificates or IMS acceptance status"],"corrective_action":"Reverse unsupported tax reduction with interest; convert future ad hoc settlements to financial credit notes; obtain recipient certificates contemporaneously.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.299033+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"518ddc7a-e958-4371-9ffb-3cb8e51b3742","control_id":"B-OUT-009","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure FOC supplies are correctly treated: taxable where Schedule I applies (related/distinct persons), ITC reversed where goods are given as gifts/free samples, and delivery documents issued.","law_refs":["CGST-ACT-SCH1-2","CIRC-92-11-2019","CGST-ACT-S17-5","CGST-RULE-55"],"required_data":["sales_register","stock_register","general_ledger","eway_bill_register"],"procedure":"1. Identify zero-value or FOC lines in the sales register and stock issues to marketing, samples, warranty and promotion cost centres.\\n2. Classify each FOC movement: related/distinct person supply (Schedule I), gift/free sample to unrelated party, BOGO or bundled offer, warranty replacement.\\n3. For Schedule I cases, verify tax paid on Rule 28 value.\\n4. For gifts and free samples to unrelated persons, verify ITC on the inputs/goods has been reversed under Section 17(5)(h).\\n5. Verify delivery challans/e-way bills accompany FOC movements above threshold.","automation":null,"expected_result":"FOC supplies to related/distinct persons taxed; ITC reversed for gifts/samples; promotional bundles priced as composite/mixed supply.","exception_conditions":"No tax on FOC supply to group entity; ITC retained on free samples; FOC goods moved without documentation.","risk_level":"medium","exposure_basis":"Tax on Schedule I FOC supplies at open-market value + interest; ITC reversal on gifts/samples + interest u/s 50(3) if utilised.","evidence_required":["FOC transaction listing","Marketing scheme documents","Valuation workings","Delivery challans"],"corrective_action":"Pay tax on Schedule I FOC supplies, reverse ITC for samples/gifts, and create distinct ERP movement types for samples, gifts and warranty replacements.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.303202+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2ad8563f-6601-4eb3-80a6-21a0f94f7fa0","control_id":"B-OUT-010","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure tax is paid at the correct time of supply on advances for services, and invoices for services are raised within 30 days of supply.","law_refs":["CGST-ACT-S12","CGST-ACT-S13","CGST-RULE-47","CGST-ACT-S50-1"],"required_data":["trial_balance","general_ledger","receivables_payables","gstr1","sales_register"],"procedure":"1. Extract customer advance ledgers and unbilled revenue/accrued income balances at each month end.\\n2. For service advances, verify tax paid in the month of receipt and reported in GSTR-1 Table 11A, with adjustment in Table 11B on invoicing.\\n3. For unbilled revenue, determine the date of completion of service and whether the invoice was raised within 30 days (Rule 47).\\n4. Compute interest on delayed payment of tax for advances and late invoicing.\\n5. Confirm advances for goods are excluded (exempted by notification) but correctly identified.","automation":null,"expected_result":"Tax on service advances paid in month of receipt; invoices issued within 30 days of completion; unbilled revenue supported by contractual milestones.","exception_conditions":"Service advances without tax; unbilled revenue relating to completed services older than 30 days; Table 11 not filed.","risk_level":"medium","exposure_basis":"Interest u/s 50(1) for the period of delay on tax relating to advances and late-invoiced services; tax itself if never invoiced.","evidence_required":["Advance and unbilled revenue ledgers","Contracts and milestone certificates","GSTR-1 Table 11 data"],"corrective_action":"Pay tax with interest on untaxed advances, report in Table 11A, and implement a monthly unbilled revenue review with tax sign-off.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.311604+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"6bf83279-b1b2-4f53-ba0a-ae50a3024d02","control_id":"B-OUT-011","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify non-operating income ledgers (scrap sale, recoveries from employees, notice pay, rent, insurance claims, liquidated damages, sale of assets) and confirm correct GST treatment.","law_refs":["CGST-ACT-S7","CGST-ACT-S15","CGST-ACT-SCH1-1"],"required_data":["trial_balance","general_ledger","gstr1","sales_register"],"procedure":"1. Map every income ledger in the trial balance to its GST treatment (taxable, exempt, non-GST, outside scope).\\n2. Sample recoveries such as canteen, transport, notice pay, liquidated damages, penalties and insurance claims; examine underlying agreements.\\n3. Verify that taxable other income has been invoiced and included in GSTR-1/GSTR-3B.\\n4. Reconcile scrap and sale-of-asset ledgers with tax invoices.\\n5. Ensure non-taxable receipts are reported appropriately in GSTR-3B/GSTR-9 (exempt/non-GST).","automation":null,"expected_result":"Every taxable other-income stream invoiced and taxed; non-GST items supported by analysis.","exception_conditions":"Rent, scrap sale or recoveries recognised as income without invoice; liquidated damages treatment undocumented.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Income ledger mapping","Agreements for recoveries","Invoices for scrap/rent"],"corrective_action":"Raise invoices and pay tax with interest on taxable income; document positions on non-taxable receipts; route all other income through the billing system.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.315626+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"36959eeb-7582-474f-b9fb-08c0f3bda486","control_id":"B-OUT-012","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure exempt and non-GST supplies are correctly reported in GSTR-1 Table 8 and GSTR-3B Table 3.1(c)/(e), and drive common-credit reversal under Rules 42/43.","law_refs":["CGST-ACT-S17-2","CGST-RULE-42","CGST-ACT-S37","CGST-ACT-S39"],"required_data":["sales_register","gstr1","gstr3b","trial_balance"],"procedure":"1. Identify exempt, nil-rated and non-GST revenue (e.g., interest income, dividend, sale of land, exempt goods) from the trial balance and sales register.\\n2. Compare with GSTR-1 Table 8 and GSTR-3B Table 3.1(c)/(e) monthly.\\n3. Verify the exempt turnover figure used in the Rule 42/43 computations matches the reported figures (including value of securities and land as prescribed).\\n4. Report differences to C-ITC-008.","automation":null,"expected_result":"Exempt/non-GST turnover reported consistently and used in reversal computations.","exception_conditions":"Interest/dividend income omitted from exempt turnover; Table 8 blank despite exempt supplies.","risk_level":"medium","exposure_basis":"Under-reversal of common credit + interest; reporting inconsistencies triggering ASMT-10.","evidence_required":["Exempt turnover workings","GSTR-1 Table 8 / GSTR-3B 3.1 extracts"],"corrective_action":"Correct reporting in subsequent returns and GSTR-9; recompute and reverse common credit.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.320377+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"92d5581d-8be5-4b23-91f0-c060dd8b7a3b","control_id":"B-OUT-013","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure reimbursements recovered from customers (freight, travel, testing, statutory fees) are included in taxable value unless all pure-agent conditions are met.","law_refs":["CGST-ACT-S15-2","CGST-RULE-33","CGST-ACT-S15"],"required_data":["sales_register","general_ledger","journal_vouchers"],"procedure":"1. Extract reimbursement/recovery ledgers and debit notes raised to customers.\\n2. Review contracts to determine whether the company acts as pure agent (contractual authorisation, recipient liability, separate disclosure, actual cost).\\n3. Verify GST charged on recoveries that do not qualify.\\n4. Check whether recoveries were passed through journal entries without invoices.","automation":null,"expected_result":"Non-qualifying reimbursements taxed at the rate of the principal supply; pure-agent recoveries documented.","exception_conditions":"Recoveries booked as credits to expense ledgers without invoices; pure agent claimed without contractual support.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Reimbursement ledger","Contracts","Debit notes / invoices"],"corrective_action":"Pay tax on non-qualifying recoveries with interest, issue tax invoices, and update contract templates for pure-agent clauses.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.324743+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2bf19381-a4b4-4faa-82d2-ad57bc2e136d","control_id":"C-ITC-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC availed in GSTR-3B is supported by books and reflected in GSTR-2B, and that eligible ITC in GSTR-2B is not lost.","law_refs":["CGST-ACT-S16-2","CGST-ACT-S16-2-AA","CGST-RULE-36-4","CIRC-170-02-2022","CGST-RULE-88D"],"required_data":["purchase_register","gstr2b","gstr3b","ims_data"],"procedure":"1. Reconcile the purchase register (ITC-eligible lines) with GSTR-2B at invoice level for each month (GSTIN + invoice number normalised + date + tax).\\n2. Classify: matched, in books not in 2B, in 2B not in books, value mismatch, period mismatch, ineligible.\\n3. Compare total ITC availed in GSTR-3B Table 4(A) for each month with books-eligible and 2B-available ITC.\\n4. Quantify excess ITC availed over 2B (Rule 36(4)/Section 16(2)(aa) exposure) and unclaimed eligible ITC in 2B.\\n5. Check for DRC-01C intimations and replies.","automation":{"type": "PR_2B_3B", "engine": "recon"},"expected_result":"ITC in GSTR-3B does not exceed eligible ITC appearing in GSTR-2B; unclaimed eligible ITC identified and claimed within Section 16(4) limit.","exception_conditions":"ITC claimed on invoices not in GSTR-2B; ITC in 2B not booked; vendor reported under wrong GSTIN; DRC-01C pending.","risk_level":"critical","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Unclaimed eligible ITC is an opportunity (E bucket) if within Section 16(4).","evidence_required":["Three-way reconciliation workpaper","GSTR-2B downloads","GSTR-3B Table 4","Vendor follow-up log"],"corrective_action":"Reverse ITC not in 2B (Table 4(B)(2)) and re-claim when reflected; follow up vendors to report; claim missed ITC within time limit; reply to DRC-01C.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.32807+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"89b59d74-c23f-4cd0-a83c-e60d32dfcb2a","control_id":"C-ITC-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect ITC claimed more than once on the same supplier invoice, including across months, GSTINs, or between purchase and expense modules.","law_refs":["CGST-ACT-S16-1","CGST-ACT-S155","CGST-ACT-S50-3"],"required_data":["purchase_register","gstr2b","journal_vouchers"],"procedure":"1. Normalise supplier GSTIN and invoice number (remove prefixes, special characters, leading zeros, FY suffix).\\n2. Identify duplicate combinations of supplier GSTIN + normalised invoice number + financial year in the purchase register.\\n3. Identify near-duplicates: same supplier, same date and same tax with different invoice numbers.\\n4. Check whether duplicates were booked in both AP and expense/journal modules.\\n5. Quantify duplicate ITC and determine utilisation dates.","automation":{"key": "DUP_ITC", "engine": "check"},"expected_result":"Each invoice yields ITC only once.","exception_conditions":"Same invoice booked twice; invoice booked against two GSTINs; revised invoice claimed alongside original.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Duplicate ITC report","Vendor invoices and payment records"],"corrective_action":"Reverse duplicate ITC with interest where utilised, reverse duplicate AP liability, and enforce duplicate-check validation in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.331075+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"a151b5d2-4016-4700-b536-087bbdc663c6","control_id":"C-ITC-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC on invoices and debit notes is not availed after 30 November following the end of the financial year of the invoice (or the annual return date, if earlier).","law_refs":["CGST-ACT-S16-4","CGST-ACT-S16-5","CIRC-211-05-2024"],"required_data":["purchase_register","gstr3b","gstr2b","gstr9"],"procedure":"1. For each ITC claim, identify the invoice/debit note date and the GSTR-3B period in which ITC was availed.\\n2. Compute the cut-off: 30 November following the FY of the invoice (for periods before the amendment, the due date of the September return), or GSTR-9 filing date if earlier.\\n3. For RCM self-invoices, use the FY of the self-invoice date as clarified by Circular 211/5/2024-GST.\\n4. Flag ITC availed in GSTR-3B filed after the cut-off (consider the filing date, not the return period).\\n5. For FY 2017-18 to 2020-21, apply Section 16(5) relief for returns filed up to 30.11.2021.","automation":{"key": "ITC_TIME_BAR_16_4", "engine": "check"},"expected_result":"No ITC availed beyond the Section 16(4) cut-off.","exception_conditions":"Prior-year invoices claimed in December or later; GSTR-3B for October filed late after 30 November; debit notes for old invoices.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Time-bar exception list","GSTR-3B filing dates","GSTR-9 filing date"],"corrective_action":"Reverse time-barred ITC with interest (if utilised); expense the tax; establish a year-end ITC sweep to claim all prior-year credit by October return.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.334398+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"67931575-97ed-4452-b63b-0b329e266a31","control_id":"C-ITC-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify ITC claimed on goods and services blocked under Section 17(5) (motor vehicles, food, health, insurance, club, travel, works contract, construction, gifts, Section 74/129/130 payments).","law_refs":["CGST-ACT-S17-5","CIRC-172-04-2022","JUDG-SAFARI-RETREATS-2024","CIRC-170-02-2022"],"required_data":["purchase_register","general_ledger","gstr3b"],"procedure":"1. Map expense GL codes and HSN/SAC to Section 17(5) categories (e.g., 9963 food, 9993 health, 9971 life/health insurance, 8703 cars, 9954 construction).\\n2. Extract ITC claimed on mapped ledgers and on capitalised civil/building works.\\n3. For exceptions (e.g., motor vehicles for specified businesses, obligatory canteen under Factories Act, same-line supplies), obtain supporting evidence.\\n4. Assess building/civil works for plant-and-machinery treatment considering the Safari Retreats judgment and the retrospective amendment to Section 17(5)(d).\\n5. Confirm blocked ITC is reported in GSTR-3B Table 4(B)(1) where availed from 2B and reversed.","automation":{"key": "BLOCKED_ITC_17_5", "engine": "check"},"expected_result":"No blocked credit retained; exceptions documented.","exception_conditions":"ITC on staff welfare/food, car hire, employee insurance, club fees, building construction, Section 74 tax payments.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["GL-to-17(5) mapping","Blocked ITC computation","Exception evidence (statutory obligation, business use)"],"corrective_action":"Reverse blocked ITC in Table 4(B)(1) with interest where utilised; add GL-level blocking rules in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.336786+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"82b69cea-2637-459e-9f07-a07268c31f9f","control_id":"C-ITC-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC is not claimed on life insurance (including key-man policies), health insurance and group mediclaim unless obligatory under a law in force.","law_refs":["CGST-ACT-S17-5","CIRC-172-04-2022"],"required_data":["purchase_register","general_ledger","bank_payments"],"procedure":"1. Extract insurance premium ledgers and classify policies by type: key-man/life, group term life, group health, accident, D&O, property, marine, product liability.\\n2. For life and health policies, determine whether the cover is obligatory under any statute (e.g., Employees'' Compensation Act/ESI exemption conditions) to fall within the proviso.\\n3. Key-man insurance (life insurance on the life of key person for company''s benefit) — confirm ITC reversed as blocked under Section 17(5)(b)(i).\\n4. Confirm ITC on business-risk insurances (property, marine, D&O liability) is retained.","automation":null,"expected_result":"ITC claimed only on insurance that is not blocked or is obligatory under law.","exception_conditions":"ITC on key-man, group mediclaim or group term life premiums without statutory obligation.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Insurance policy schedules","Premium invoices","Statutory obligation analysis"],"corrective_action":"Reverse ineligible insurance ITC with interest where utilised; tag insurance types in AP for automatic blocking.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.33939+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fb67a184-d483-498c-9485-e0e00821b33e","control_id":"C-ITC-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC is reversed where value plus tax is not paid to the supplier within 180 days of the invoice date, and re-availed on payment.","law_refs":["CGST-RULE-37","CGST-ACT-S16-2","CIRC-170-02-2022"],"required_data":["receivables_payables","purchase_register","bank_payments","gstr3b"],"procedure":"1. Obtain AP ageing as on each month end with invoice-level detail and tax component.\\n2. Identify invoices outstanding beyond 180 days (including partial payments, retention money, disputed invoices).\\n3. Exclude deemed-paid items (e.g., RCM, specified deemed supplies without consideration).\\n4. Verify reversal in GSTR-3B Table 4(B)(2) in the period following the 180th day and re-claim after payment in Table 4(A)(5).\\n5. Assess interest where ITC reversed late (Section 50(3), only if utilised).","automation":null,"expected_result":"Reversals made for all invoices crossing 180 days unpaid; re-claims supported by payments.","exception_conditions":"Retention money/withheld amounts not reversed; disputed invoices ignored; re-claim before payment.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Temporary reversal; re-available on payment (E bucket).","evidence_required":["AP ageing with GST component","Reversal and re-claim workings","GSTR-3B Table 4 extracts"],"corrective_action":"Reverse ITC on overdue payables, track for re-claim, and automate a 180-day AP report linked to GST reversal.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.34343+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"12b63596-ab84-4112-8fa8-302cde657670","control_id":"C-ITC-007","version":1,"effective_from":"2022-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC on invoices reported in GSTR-1 by suppliers who have not filed GSTR-3B by 30 September following the year end is reversed by 30 November.","law_refs":["CGST-RULE-37A","CGST-ACT-S16-2"],"required_data":["gstr2b","gstr2a","vendor_master","purchase_register"],"procedure":"1. Download GSTR-2B for each month and identify supplier records flagged with GSTR-3B non-filing (Rule 37A advisory section) and supplier filing status from GSTR-2A.\\n2. Quantify ITC availed from suppliers who had not filed GSTR-3B for the relevant period as on 30 September.\\n3. Verify reversal in GSTR-3B on or before 30 November and re-claim upon subsequent supplier filing.\\n4. Engage with procurement to withhold payments to non-compliant vendors.","automation":null,"expected_result":"Rule 37A reversals timely made and tracked for re-claim.","exception_conditions":"ITC retained despite supplier non-filing; reversal made after 30 November.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Supplier filing status report","Rule 37A reversal working","GSTR-3B extracts"],"corrective_action":"Reverse ITC with interest where applicable; re-claim when supplier files; incorporate supplier filing status in payment release.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.346957+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"440c7797-afce-42b2-81e7-28309f28177d","control_id":"C-ITC-013","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer","sez_supplier"],"objective":"Ensure ITC on shipping line, CHA and logistics invoices relating to goods held in FTWZ or customs warehouses is claimed only by the correct recipient GSTIN and only where the services relate to taxable/zero-rated supplies of the claimant.","law_refs":["CGST-ACT-S16-1","CGST-ACT-S16-2","CGST-ACT-SCH3-8A","IGST-ACT-S7-5"],"required_data":["purchase_register","bills_of_entry","general_ledger","gstr2b"],"procedure":"1. Extract invoices from shipping lines, CFS, CHA and freight forwarders and map each to the import consignment (BL/BOE number).\\n2. Identify consignments landed into FTWZ/SEZ units or customs bonded warehouses and their subsequent disposal (DTA clearance by the company, sale while warehoused, re-export).\\n3. Verify invoices are in the name and GSTIN of the company (not the FTWZ unit) and that the services were received by the company.\\n4. Where goods are sold while in FTWZ/warehouse (Schedule III para 8(a)), evaluate whether ITC on attributable services requires reversal as related to non-supply (Rule 42).\\n5. Where FTWZ unit is the recipient, confirm charges should have been zero-rated to the SEZ unit and not claimed as ITC in DTA.","automation":null,"expected_result":"ITC on logistics charges claimed only where the company is the recipient and the goods feed taxable or zero-rated supplies.","exception_conditions":"ITC claimed on charges billed to FTWZ unit; ITC retained on services linked to warehoused sales outside GST; IGST charged by shipping line on SEZ-bound services.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Consignment-wise logistics cost mapping","BOE/BL copies","FTWZ disposal records"],"corrective_action":"Reverse ineligible ITC, request corrected invoices (correct GSTIN/zero-rating) from vendors, and define consignment-level ITC coding for FTWZ flows.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.37646+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"8d02cd82-accf-4379-a0c7-3c625bd5a37b","control_id":"C-ITC-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify monthly and annual reversal of common ITC attributable to exempt supplies and non-business use.","law_refs":["CGST-ACT-S17-2","CGST-RULE-42","CGST-RULE-43","CIRC-170-02-2022"],"required_data":["purchase_register","gstr3b","trial_balance","sales_register","fixed_asset_register"],"procedure":"1. Classify ITC into T1 (non-business), T2 (exclusively exempt), T3 (blocked) and common credit C2 for inputs/input services; identify common capital goods for Rule 43.\\n2. Compute exempt turnover ratio (including exempt and non-taxable supplies as prescribed) for each month and the year.\\n3. Recompute monthly D1/D2 reversals and the annual true-up; compare with reversals in GSTR-3B Table 4(B)(1).\\n4. Compute Rule 43 monthly reversal for common capital goods over 60 months.\\n5. Compute interest on short reversal from April following the year end as per Rule 42(2).","automation":null,"expected_result":"Monthly provisional and annual final reversals correctly computed and reported.","exception_conditions":"No reversal despite exempt income (e.g., interest, sale of land, exempt services); annual true-up not done.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Interest per Rule 42(2)/43 on short reversal.","evidence_required":["Rule 42/43 computation","Exempt turnover workings","GSTR-3B reversal extracts"],"corrective_action":"Reverse short computed credit with interest and institutionalise a monthly Rule 42/43 working signed off by tax.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.351443+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9b60f7ed-6f8e-480c-ba37-a376aeea058d","control_id":"C-ITC-009","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect ITC availed on invoices from suppliers whose GSTIN was invalid, cancelled or suspended on the invoice date.","law_refs":["CGST-ACT-S16-2","CGST-ACT-S29","CGST-RULE-86A"],"required_data":["purchase_register","vendor_master","gstr2b"],"procedure":"1. Run GSTIN validation on all purchase register lines carrying ITC.\\n2. Match invoice dates with supplier cancellation effective dates.\\n3. Quantify ITC on invalid/cancelled GSTINs and check its presence in GSTR-2B.\\n4. Check if any Rule 86A blocking has been imposed on the electronic credit ledger.","automation":{"key": "INVALID_GSTIN", "engine": "check"},"expected_result":"No ITC from invalid or cancelled GSTINs.","exception_conditions":"ITC on invoices with typo GSTINs or from cancelled suppliers; ledger blocked under Rule 86A.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["GSTIN status report for purchase lines","Vendor correspondence"],"corrective_action":"Reverse ineligible ITC, recover tax from vendor, correct vendor master, and pursue unblocking with documents where ITC is genuine.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.355701+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"d3d1933f-5dcc-481a-8414-b8c9bb973c4c","control_id":"C-ITC-010","version":1,"effective_from":"2024-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure IMS actions on inward records are deliberate and consistent with books, so GSTR-2B reflects only valid ITC and credit notes.","law_refs":["ADV-IMS","CGST-ACT-S16-2-AA","CGST-RULE-36-4"],"required_data":["ims_data","gstr2b","purchase_register"],"procedure":"1. Download IMS data for each period with action status (accepted, rejected, pending, deemed accepted).\\n2. Match IMS records with purchase register; ensure records not in books (or disputed) are rejected or kept pending with justification.\\n3. Ensure credit notes from suppliers are not rejected merely to avoid ITC reduction where the credit note is genuine.\\n4. Verify pending records are reviewed before the time limit for ITC and that GSTR-2B is recomputed after late actions.\\n5. Document approval matrix for IMS actions.","automation":null,"expected_result":"IMS actions consistent with books; no blanket deemed acceptance of records not in books.","exception_conditions":"Records accepted though goods/services not received; genuine supplier credit notes rejected; large pending volumes near cut-off.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Rejecting a valid supplier credit note may lead to ITC reduction demands.","evidence_required":["IMS action log","Books vs IMS match report","Approval evidence"],"corrective_action":"Rectify IMS actions before 2B generation, recompute GSTR-2B where permitted, and implement a weekly IMS review routine.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.361515+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9cb5c929-91bf-412a-86e2-253656f5db21","control_id":"C-ITC-011","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC is reduced for credit notes issued by suppliers (returns, discounts, rate revisions) and accounted in books.","law_refs":["CGST-ACT-S34","CGST-ACT-S15-3","ADV-IMS","CGST-ACT-S16-2-AA"],"required_data":["gstr2b","ims_data","purchase_register","journal_vouchers"],"procedure":"1. Extract supplier credit notes from GSTR-2B/IMS (B2B-CDNR).\\n2. Match with debit notes/credit notes booked in purchase register and journal vouchers.\\n3. Identify credit notes in GSTR-2B not booked and verify ITC reduction in GSTR-3B.\\n4. Identify volume rebates/discounts received as financial credit notes and confirm no ITC impact required.","automation":null,"expected_result":"ITC reduced for all supplier credit notes in GSTR-2B.","exception_conditions":"Supplier credit notes not booked; ITC not reduced; rebates received without supplier credit note where GST impact intended.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["CDNR reconciliation","Supplier statements"],"corrective_action":"Reverse ITC for unbooked supplier credit notes with interest where utilised and include CDNR matching in monthly close.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.36746+00:00"}') on conflict do nothing;
